namespace Trauma {
	struct InputState {
		float moveX = 0.0f;
		bool jump = false;
	};

	struct ObjectState {
		olc::vf2d position;
		olc::vf2d velocity;
		bool grounded = false;
		uint32_t lastInput = 0;
	};

	constexpr uint8_t MaxPlayers = 16;
